import{_t as e,it as t,n,rt as r}from"./chunks/framework.CfRzmOnu.js";var i=JSON.parse(`{"title":"For Agents","description":"","frontmatter":{},"headers":[],"relativePath":"ai/agents.md","filePath":"ai/agents.md","lastUpdated":1791960221000}`),a={name:`ai/agents.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="for-agents" tabindex="-1">For Agents <a class="header-anchor" href="#for-agents" aria-label="Permalink to “For Agents”">​</a></h1><p>在 XiHan.BasicApp 上做二次开发时，怎样让 Claude Code、Cursor、Codex、GitHub Copilot 这类 AI 编程工具写出符合项目约定的代码。</p><div class="tip custom-block"><p class="custom-block-title">和「AI 模块」不是一回事</p><p>本册讲的是<strong>用 AI 工具开发 BasicApp</strong>。BasicApp 自带的大模型接入、智能体与知识库功能见后端手册的 <a href="./../backend/ai">AI 模块</a>。</p></div><p>BasicApp 是克隆下来二次开发的应用，没有单独的命令行或 MCP 服务端；AI 工具需要的资料分三处：仓库自带的 Agent 规范与技能、后端依赖的 <a href="https://framework.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.Framework</a> 与前端依赖的 <a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI</a> 各自的 MCP 服务端，以及本站的机读文档。</p><h2 id="复制这段提示词" tabindex="-1">复制这段提示词 <a class="header-anchor" href="#复制这段提示词" aria-label="Permalink to “复制这段提示词”">​</a></h2><p>把下面这段放进对话，或补进仓库根 <code>AGENTS.md</code> 的开头：</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>这是基于 XiHan.BasicApp 的项目：后端 .NET + XiHan.Framework（backend/），前端 Vue 3 + XiHan.UI（frontend/）。</span></span>
<span class="line"><span>开始前先读仓库根的 AGENTS.md，并按任务读取 .agents/skills/ 下对应的技能：</span></span>
<span class="line"><span>后端读 backend-development，前端读 frontend-development，跨前后端的 DTO、权限码、菜单与租户契约读 fullstack-contracts。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>框架与组件库的 API 以项目引用的版本为准，不要凭记忆写：</span></span>
<span class="line"><span>- 后端的包、模块类、[DependsOn] 与配置键用 xihan-framework MCP 工具查（xihan_framework_info / xihan_framework_config / xihan_framework_search）；</span></span>
<span class="line"><span>- 前端的组件名、部件、Props 与设计令牌用 xihan-ui MCP 工具查（xihan_ui_info / xihan_ui_demo / xihan_ui_parts / xihan_ui_token）。</span></span>
<span class="line"><span>没有 MCP 时读 https://basicapp.docs.xihanfun.com/llms.txt、https://framework.docs.xihanfun.com/llms.txt 与 https://ui.docs.xihanfun.com/llms.txt。</span></span></code></pre></div><h2 id="仓库自带的-agent-规范" tabindex="-1">仓库自带的 Agent 规范 <a class="header-anchor" href="#仓库自带的-agent-规范" aria-label="Permalink to “仓库自带的 Agent 规范”">​</a></h2><table tabindex="0"><thead><tr><th>文件</th><th>内容</th></tr></thead><tbody><tr><td><code>AGENTS.md</code></td><td>仓库概览、开始前必须做的检查、目录结构、常用命令、后端与前端架构约束、前后端契约、配置运维、测试与提交规范、禁止事项</td></tr><tr><td><code>CLAUDE.md</code></td><td>指向 <code>AGENTS.md</code> 的链接，Claude Code 打开仓库时自动读取</td></tr><tr><td><code>.agents/skills/</code></td><td>按任务划分的技能，<code>.claude/skills</code> 链接到这里</td></tr></tbody></table><p>技能按任务加载，不必一次读完：</p><table tabindex="0"><thead><tr><th>技能</th><th>什么时候用</th></tr></thead><tbody><tr><td><code>backend-development</code></td><td>实现或重构后端模块：Dynamic API、DDD/CQRS、SqlSugar、实体、仓储、权限、租户、事务、种子</td></tr><tr><td><code>frontend-development</code></td><td>实现或重构 Vue 管理端：XiHan.UI、类型化 API、Pinia、动态路由、插件模块、权限可见性、统一视觉</td></tr><tr><td><code>fullstack-contracts</code></td><td>改动跨前后端的契约：Dynamic API 服务与 DTO、权限码、租户隔离、菜单路由、可选模块、配置与部署边界</td></tr><tr><td><code>test-review</code></td><td>审查测试是否有效、重复、过度 mock</td></tr><tr><td><code>commit-msg</code> · <code>create-pr</code> · <code>changelog-collect</code> · <code>version-release</code> · <code>issue-reply</code></td><td>提交、PR、更新日志、发版与 Issue 回复</td></tr></tbody></table><p>Claude Code 与 Codex 打开仓库即可读到 <code>AGENTS.md</code>；Cursor、GitHub Copilot 等工具可以在各自的规则文件里写一句「先读仓库根的 AGENTS.md」。</p><h2 id="接入两个-mcp-服务端" tabindex="-1">接入两个 MCP 服务端 <a class="header-anchor" href="#接入两个-mcp-服务端" aria-label="Permalink to “接入两个 MCP 服务端”">​</a></h2><p>后端用 XiHan.Framework 的 MCP 服务端查包、模块与配置键，前端用 XiHan.UI 的 MCP 服务端查组件 API、示例与令牌。两者都离线、按版本钉住，配置方法见 <a href="./mcp">MCP Server</a>。</p><p>最省事的做法是在仓库根运行两条 <code>setup</code>，各自读出后端与前端引用的版本，写进同一个 <code>.mcp.json</code>：</p><div class="language-bash"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">dnx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> XiHan.Framework.Cli</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --yes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -y</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @xihan-ui/cli</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> setup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --client</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude</span></span></code></pre></div><h2 id="机读文档" tabindex="-1">机读文档 <a class="header-anchor" href="#机读文档" aria-label="Permalink to “机读文档”">​</a></h2><p>本站在构建时产出 <a href="./llms">机读资产</a>：<code>llms.txt</code> 索引、<code>llms-full.txt</code> 全站正文、<code>llms-backend.txt</code> 后端手册与 <code>llms-frontend.txt</code> 前端手册，每一页在站点地址后加 <code>.md</code> 即可取到 Markdown。</p><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to “相关”">​</a></h2><ul><li><a href="./../project-structure">目录结构与代码地图</a> · <a href="./../api-guide">接口对接指南</a> · <a href="./../dev-environment">开发环境</a></li><li><a href="https://framework.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.Framework 的 AI 辅助开发</a> · <a href="https://ui.docs.xihanfun.com/ai/agents" target="_blank" rel="noreferrer">XiHan.UI 的 AI 辅助开发</a></li></ul>`,20)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};